export function billRows(groups,paid,tables,zones){
  const tableMap=new Map(tables.map(t=>[t.id,t])),zoneMap=new Map(zones.map(z=>[z.id,z.name])),settled=new Map();
  for(const order of paid){const key=order.table_id+'|'+order.paid_at;if(!settled.has(key))settled.set(key,[]);settled.get(key).push(order)}
  const rows=groups.map(g=>({...g,grandTotal:Number(g.grandTotal??g.total??0),key:'unpaid-'+g.tableId,paid:false,date:g.orders[0]?.created_at}));
  for(const [key,orders] of settled){const first=orders[0],table=tableMap.get(first.table_id);rows.push({key,orders,table,tableId:first.table_id,zoneName:zoneMap.get(table?.zone_id),grandTotal:Number(first.bill_total??orders.reduce((sum,order)=>sum+Number(order.settled_total??order.total),0)),paid:true,date:first.paid_at||first.created_at,method:first.payment_method||'other'})}
  return rows.map(row=>({...row,number:[...new Set(row.orders.map(o=>o.receipt_number||o.id))].join(', ')})).sort((a,b)=>new Date(b.date)-new Date(a.date));
}
