  const visible=rows.filter(row=>(status==='all'||row.paid===(status==='paid'))&&(zone==='all'||row.table?.zone_id===zone)&&(method==='all'||row.paid&&row.method===method)&&[row.number,row.table?.table_number,row.zoneName,date(row)].join(' ').toLowerCase().includes(search.trim().toLowerCase()));
